/**
 * CORRECAO (2a tentativa) - duas barras de rolagem na agenda
 *
 * POR QUE A PRIMEIRA TENTATIVA FALHOU
 *
 * Eu tinha liberado a rolagem so no eixo vertical, mantendo o horizontal
 * travado. Em CSS isso nao funciona: quando um eixo esta travado, o
 * navegador converte o outro de "livre" para "com rolagem" sozinho. Ou
 * seja, a rolagem interna continuou existindo - so que com um container
 * gigante, o que deixou a rolagem estranha ("andava centimetros").
 *
 * Havia ainda um segundo problema: a moldura da agenda tem corte de
 * conteudo, o que cortaria o calendario mesmo se o primeiro problema
 * fosse resolvido.
 *
 * O QUE MUDOU AGORA
 *
 * No computador, com ate 2 profissionais na tela (que e o caso normal),
 * os DOIS eixos ficam livres e a moldura deixa de cortar - entao quem rola
 * passa a ser a pagina inteira, com uma barra so, e o ultimo horario do
 * dia aparece completo.
 *
 * Com 3 ou mais profissionais lado a lado, a rolagem horizontal e
 * necessaria e a agenda mantem a rolagem propria (nao da para ter um eixo
 * rolando e o outro livre, pelo motivo explicado acima).
 *
 * No CELULAR nada muda em nenhum caso.
 *
 * Como usar: coloque este arquivo na RAIZ do projeto e rode
 *     node corrigir-rolagem-agenda-2.mjs
 *
 * E seguro rodar duas vezes: se ja estiver aplicado, ele avisa e pula.
 * Tambem e seguro rodar mesmo tendo rodado a primeira versao - este
 * arquivo substitui o resultado dela por completo.
 */

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { Buffer } from "node:buffer";

const ARQUIVO = "app/(app)/agenda/components/AgendaCalendar.tsx";

console.log("\nCorrecao (2a tentativa) - rolagem da agenda\n");

if (!existsSync(ARQUIVO) || !existsSync("package.json")) {
  console.error("ERRO: nao encontrei o arquivo do projeto:\n");
  console.error("   " + ARQUIVO + "\n");
  console.error(
    "Coloque este script na pasta raiz do projeto (a mesma que tem o package.json) e rode de novo.\n",
  );
  process.exit(1);
}

